#!/usr/bin/env python3
"""Prepare standalone source/binary/checker pins without opening target CNF.
Never rebuild after submission or after a result directory exists.
"""
import hashlib,json,shutil,subprocess
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2]
OLD=ROOT/'benchmarks/probes/20261007-fixed44-directcsp-stream-admission'
assert not any(HERE.glob('result-*')) and not (HERE/'submission.json').exists()
def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
compile_command=['g++','-O2','-std=c++17','-Wall','-Wextra','-Wconversion',str(HERE/'census.cpp'),'-llzma','-lcrypto','-o',str(HERE/'pins/census')]
subprocess.run(compile_command,check=True)
test=subprocess.run(['python3',str(HERE/'test_controls.py')],check=True,capture_output=True,text=True)
(HERE/'fixed-controls.txt').write_text(test.stdout)
for name in ['census.cpp','check_original_rup.py','test_controls.py']:shutil.copyfile(HERE/name,HERE/'pins'/name)
old=json.loads((OLD/'launch-manifest.json').read_text());inp=old['input'].copy()
authority=json.loads((ROOT/inp['authority_path']).read_text())
assert authority[inp['authority_field']][inp['authority_key']]==inp['sha256']
prior=json.loads((OLD/'result-1751806-0/census.json').read_text())
assert prior['input_hash_complete'] and prior['input_file_sha256']==inp['sha256'] and prior['source_complete'] and prior['query_complete']
seed=prior['seed'];seed_blocker=min(-e['signed_literal'] for e in prior['outgoing_neighbors'] if e['signed_literal']<0)
original_link=next(e['premise'] for e in prior['outgoing_neighbors'] if e['signed_literal']==-seed_blocker)
paths=[ROOT/inp['authority_path'],OLD/'launch-manifest.json',OLD/'result-1751806-0/census.json',OLD/'result-1751806-0/outcome.json',HERE/'census.cpp',HERE/'pins/census.cpp',HERE/'pins/census',HERE/'check_original_rup.py',HERE/'pins/check_original_rup.py',HERE/'test_controls.py',HERE/'pins/test_controls.py',HERE/'fixed-controls.txt',HERE/'launch.py',HERE/'census.sbatch',HERE/'prepare.py',ROOT/old['bindings'][-1]['path'],ROOT/'benchmarks/probes/20261007-fixed44-blocker-cover-admission/launch-manifest.json',ROOT/'benchmarks/probes/20261007-fixed44-blocker-cover-admission/result-1751830-0/outcome.json']
m={'schema':'blocker-support-launch-v1','source_snapshot_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'input':inp,'selection':dict(seed_or=seed,seed_blocker=seed_blocker,original_seed_link_occurrence=original_link,authorized_domain_begin=0,selection_authority='Retained complete-stream result chooses minimum negative seed neighbor; authorized domain row0 is a candidate selection, authenticated by exact OR membership across all8 positions before any deduction.'),'resources':old['resources'],'limits':dict(census_seconds=14,census_process_seconds=15,combined_process_seconds=30,allocation_bytes=256*1024*1024,metadata_bytes=32*1024*1024,query_work=10000000,checker_work=10000000,blocker_covers=1,blockers=32,positions=8,domain_width=4,fixed_positions=7,residual_pairs=4,binary_cases=24,maximum_binary_conflict_premises=1024,maximum_certificate_literal_rows=2*inp['variables']),'source_grammar':'One positive32-blocker cover,32 one-sided b->key and b->negative-lock pairs; sixteen exact4-value original domains;32 exact positive-key-input OR definitions. No blocker AND converse or blocker-cover AMO inferred. Each unauthorized value maps bijectively to one authorized input value by exact OR membership.','finite_work':'Inherited compressed/decoded/header caps; <=M binary records,<=2M CSR edges, fixed indexing passes, capped sort comparisons; independent10M metered query operations including binary-closure edges and searches. Checker separately hashes entire compressed input and parses all original terminating-zero occurrences within the same byte/header caps, verifies closed masks against every original binary (2 metered implications per binary), certifies excluded cases by original-binary RUP, then <=10M combined certificate/witness/RUP operations. C++ certificate-mask construction is additionally bounded by24*(2*variables) node inspections and at most2*variables certificate literal rows. Sequential whole experiment externally bounded30s.','absence_and_binary_exclusion':'Independent checker rereads complete original input and validates every physical occurrence and absence; binary closure certificates cover8 individual residual values and16 pairs under compatible14-literal prefix. Every unexcluded case has a consistent partial assignment closed under every original binary implication; every excluded case carries original-binary RUP witnesses, independently checked. All4 final tuples independently original-CNF RUP checked.','admission_gate':'Four independently RUP-checked aligned tuples, with at least one absent and not original-binary-implied. Require>=3 independently binary-unexcluded values per residual domain and>=2 binary-unexcluded off-diagonal supports for every unexcluded value after aligned relation; no global SAT/allowed-tuple claim under other large clauses. Native integration/solver benefit requires root review. No fresh identities or model change.','compile_command':compile_command,'compiler_version':subprocess.check_output(['g++','--version'],text=True).splitlines()[0],'liblzma_version':subprocess.check_output(['pkg-config','--modversion','liblzma'],text=True).strip(),'libcrypto_version':subprocess.check_output(['pkg-config','--modversion','libcrypto'],text=True).strip(),'bindings':[dict(path=str(p.relative_to(ROOT)),sha256=digest(p)) for p in paths],'storage_guard':old['storage_guard'],'solver_run':False,'submission':'not_submitted'}
(HERE/'launch-manifest.json').write_text(json.dumps(m,indent=2)+'\n')
(HERE/'launch-manifest.sha256').write_text(digest(HERE/'launch-manifest.json')+'  launch-manifest.json\n')
print(test.stdout,end='');print('Prepared only; no target inspection or submission.')
